class Solution {
public:
    int gcd(long long a, long long b)
    {
        return b == 0 ? a : gcd(b, a % b);
    }
    int maxLength(vector<int>& nums) {
        int n = nums.size();
        long long prod = nums[0];
        int l = 0, r= 1;
        int ans = 2;
        while(r<n)
        {
            if(gcd(prod,nums[r])==1)
            {
                prod = prod*nums[r];
                r++;
                if(ans<r-l+1)
                    ans= r-l;
            }
            else
            {
                prod=prod/nums[l];
                l++;
                if(l==r)
                    r++;
            }
        }
        return ans;
    }
};
